import{_ as a,o as i,c as o,ah as t}from"./chunks/framework.D4KxWb5R.js";const h=JSON.parse('{"title":"Mon compte","description":"","frontmatter":{},"headers":[],"relativePath":"guide/account.md","filePath":"src/guide/account.md"}'),s={name:"guide/account.md"};function r(n,e,l,c,u,p){return i(),o("div",null,[...e[0]||(e[0]=[t('<h1 id="mon-compte" tabindex="-1">Mon compte <a class="header-anchor" href="#mon-compte" aria-label="Permalink to &quot;Mon compte&quot;">​</a></h1><p>Ouvrez le menu de votre nom, en bas à gauche, puis <strong>Paramètres</strong>. Les paramètres comptent cinq onglets : Profil, Sécurité, Notifications, Apparence et Langue.</p><h2 id="profil" tabindex="-1">Profil <a class="header-anchor" href="#profil" aria-label="Permalink to &quot;Profil&quot;">​</a></h2><p>Modifiez votre nom et votre adresse e-mail, et ajoutez une photo de profil. Changer d&#39;adresse e-mail demande de vérifier la nouvelle par le lien reçu.</p><p>Votre poste, votre périmètre et vos accès ne se modifient pas ici : ils relèvent de l&#39;administrateur général.</p><h2 id="securite" tabindex="-1">Sécurité <a class="header-anchor" href="#securite" aria-label="Permalink to &quot;Sécurité&quot;">​</a></h2><h3 id="mot-de-passe" tabindex="-1">Mot de passe <a class="header-anchor" href="#mot-de-passe" aria-label="Permalink to &quot;Mot de passe&quot;">​</a></h3><p>Saisissez le mot de passe actuel, puis le nouveau (12 caractères au moins par défaut). Changer de mot de passe oublie tous vos appareils mémorisés.</p><h3 id="application-d-authentification" tabindex="-1">Application d&#39;authentification <a class="header-anchor" href="#application-d-authentification" aria-label="Permalink to &quot;Application d&#39;authentification&quot;">​</a></h3><ol><li><strong>Activer la 2FA</strong>, puis confirmez votre mot de passe.</li><li>Scannez le code QR avec votre application (ou saisissez la clé de configuration).</li><li>Saisissez le code à 6 chiffres affiché par l&#39;application.</li><li>Conservez les <strong>codes de récupération</strong> dans un gestionnaire de mots de passe : chacun permet une connexion si vous perdez votre téléphone, une seule fois.</li></ol><p>Une fois l&#39;application active, c&#39;est elle qui vous donne le code à la connexion, à la place de l&#39;e-mail. <strong>Désactiver la 2FA</strong> revient au code par e-mail si la double authentification est exigée pour vous.</p><h3 id="cles-d-acces" tabindex="-1">Clés d&#39;accès <a class="header-anchor" href="#cles-d-acces" aria-label="Permalink to &quot;Clés d&#39;accès&quot;">​</a></h3><p><strong>Ajouter une clé d&#39;accès</strong> enregistre une passkey (empreinte, visage, code du téléphone ou clé de sécurité) sous le nom de votre choix. Vous vous connectez ensuite sans mot de passe ni code. Supprimez une clé que vous n&#39;utilisez plus.</p><h3 id="appareils-memorises" tabindex="-1">Appareils mémorisés <a class="header-anchor" href="#appareils-memorises" aria-label="Permalink to &quot;Appareils mémorisés&quot;">​</a></h3><p>La liste montre les navigateurs pour lesquels vous avez coché « Se souvenir de cet appareil » en saisissant un code reçu par e-mail : ils ne vous demandent plus de code pendant 30 jours. <strong>Oublier</strong> retire un appareil ; <strong>Tout oublier</strong> les retire tous. Faites-le si vous perdez un appareil ou l&#39;avez utilisé sur un poste partagé.</p><h2 id="notifications" tabindex="-1">Notifications <a class="header-anchor" href="#notifications" aria-label="Permalink to &quot;Notifications&quot;">​</a></h2><p>Voir <a href="./notifications.html#choisir-comment-etre-prevenu">Notifications</a>.</p><h2 id="apparence" tabindex="-1">Apparence <a class="header-anchor" href="#apparence" aria-label="Permalink to &quot;Apparence&quot;">​</a></h2><p>Choisissez le thème clair, sombre ou celui de votre système.</p><h2 id="langue" tabindex="-1">Langue <a class="header-anchor" href="#langue" aria-label="Permalink to &quot;Langue&quot;">​</a></h2><p>Choisissez l&#39;anglais ou le français. La langue s&#39;applique à tout l&#39;intranet, au back-office M&#39;City et à vos notifications.</p>',21)])])}const m=a(s,[["render",r]]);export{h as __pageData,m as default};
